        if (ra == rb) return ra;
        if (sizeProc[ra] < sizeProc[rb]) {
            int t = ra;
            ra = rb;
            rb = t;
        }
        parentProc[rb] = ra;
        sizeProc[ra] += sizeProc[rb];
        return ra;
