                if (compSum[reps[i]] >= p) {
                    int other = findSCC(rootSCC(reps[i]));
                    sccRep = unionSCC(sccRep, other);
                }
            }

            sccRep = findSCC(sccRep);
            value[sccRep] = total;

            for (int i = 0; i < cnt; i++) {
                unionProc(idx, reps[i]);
            }

            int newRep = findProc(idx);
            compSum[newRep] = total;
            rootSCC[newRep] = sccRep;
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < K; i++) {
            long ans = value[findSCC(i)];
            sb.append(ans);
            if (i % M == M - 1) {
                sb.append('\n');
            } else {
                sb.append(' ');
            }
        }

        System.out.print(sb);
    }

    static int rootSCC(int rep) {
        return rootSCCArr[rep];
    }

    static int[] rootSCCArr;

    static {
        rootSCCArr = null;
    }
}
